function* fib() {                 // infinite lazy sequence
  let [a, b] = [0n, 1n];
  while (true) {
    yield a;                      // suspend with the frame intact
    [a, b] = [b, a + b];
  }
}

for (const n of fib()) {          // consumer decides how many
  if (n > 100n) break;            // break() closes the generator
  console.log(n);
}

