async function* pages(url) {
  let next = url;
  while (next) {
    const res = await fetch(next);       // awaited per element
    const body = await res.json();
    yield body.items;                    // one page per pull
    next = body.next;
  }
}

for await (const page of pages('/api/items')) console.log(page.length);
